def evaluate_postfix(tokens):
    stack = []
    for token in tokens:
        if token not in {"+","-","*","/"}:
            stack.append(int(token)); continue
        b, a = stack.pop(), stack.pop()
        if token == "+": value = a+b
        elif token == "-": value = a-b
        elif token == "*": value = a*b
        else: value = (abs(a)//abs(b)) * (-1 if (a<0) != (b<0) else 1)
        stack.append(value)
    return stack[0]

