def cross_entropy_gradient(logits, labels):
    e = np.exp(logits-logits.max(axis=1,keepdims=True))
    gradient = e/e.sum(axis=1,keepdims=True)
    gradient[np.arange(len(labels)),labels.astype(int)] -= 1
    return gradient/len(labels)

