def smoothed_loss(logits, labels, epsilon=0.1):
    z = logits-logits.max(axis=1,keepdims=True)
    log_p = z-np.log(np.exp(z).sum(axis=1,keepdims=True))
    nll = -log_p[np.arange(len(labels)),labels.astype(int)]
    return float(np.mean((1-epsilon)*nll-epsilon*log_p.mean(axis=1)))

