def knn_predict(x, labels, queries, k):
    out = []
    for query in queries:
        neighbors = np.argsort(((x-query)**2).sum(axis=1),kind="stable")[:k]
        classes, counts = np.unique(labels[neighbors].astype(int),return_counts=True)
